+        {
+            directory
+        }
+        _ => {
+            eprintln!("{USAGE}");
+            return Ok(2);
+        }
+    };
+    match validate_directory(Path::new(directory)) {
+        Ok(count) => {
+            println!("agent registry: {count} package(s) valid (not activated)");
+            Ok(0)
+        }
